import { useState, u } from 'react';
import { useForm, Controller } from 'react-hook-form';
import { yupResolver } from '@hookform/resolvers/yup';
import { Box, Button, Checkbox, Container, FormControlLabel, TextField, Typography } from '@mui/material';
import schema from '../validations/formAppSchema';

export default function FormApp() {
  const [sent, setSent] = useState(false);

  useEffect(() => {
  const sub = watch(() => setSent(false));
  return () => sub.unsubscribe();
}, [watch]);

  const {register, handleSubmit, formState: {errors, isSubmitting}, reset, control, watch} = useForm({
    defaultValues: {
      name: '',
      email: '',
      title: '',
      message: '',
      agreement: false,
    },
    resolver: yupResolver(schema),
  });

  const onSubmit = async (data) => {
    //ここでAPI送信などを実装(現在は疑似送信)
    await new Promise(resolve => setTimeout(resolve, 1000));
    setSent(true);
    reset();

  };

  return (
    <Container component="form" maxWidth="sm" onSubmit={handleSubmit(onSubmit)} noValidate sx={{my: 2}}>{/* formタグを使用しない */}
      {sent &&
      <Box role="status" aria-live="polite">{/* role="status"はWAI-ARIAの属性の1つで、ウェブページ上の状態や進捗状況をスクリーンリーダーに伝えるために使用、
      これによりユーザーはWebサイトやアプリケーションの状態の変化を音声や点字で知ることができる、
      aria-live="polite"を設定した要素が更新された場合、スクリーンリーダーはユーザーが他の操作をしていないタイミングでその変更を読み上げる、
      これによりユーザーの操作を妨げることなく重要な情報を伝えることができる */}
        <Typography sx={{color: 'success.main'}}>お問い合わせありがとうございます。内容を確認後、担当者よりご連絡いたします。</Typography>
      </Box>}

      <TextField
      id="name"
        label="お名前"
        autoComplete="name"//autoComplete属性を付けることでブラウザがフィールドの役割を明確に認識し正しい候補を提案できる
        placeholder="山田 太郎"
        error={!!errors.name}//MUIのTextFieldのerrorプロパティはtrueのときだけ赤枠＆エラースタイルを適用する仕様、
        //errors.nameが存在するかどうかを真偽値に変換して渡す必要有
        helperText={errors.name?.message}
                fullWidth
        margin="none"

                slotProps={{//slotPropsは内部パーツだけをピンポイントでカスタマイズできる、余計なCSSの上書きやテーマ変更をせずに局所的に調整できる
    formHelperText: {sx: {fontSize: 14}}
  }}

        sx={{my: 2}}
        {...register('name')}//左記によりname="name"が自動で設定される、値変更時やフォーカスアウト時にReact Hook Formが処理できる、
        //DOM参照がセットされる＝この1行でフォーム要素をReact Hook Formの管理下に置くというセットアップが完了する
        />

      <TextField
      id="email"
        label="メールアドレス"
                autoComplete="email"

        placeholder="taro@example.com"
        type="email"
        error={!!errors.email}
        helperText={errors.email?.message}
                fullWidth
        margin="none"

        slotProps={{
    formHelperText: {sx: {fontSize: 14}}
  }}
                sx={{my: 2}}

        {...register('email')}
      />

      <TextField
      id="title"
        label="件名"
        autoComplete="off"
        placeholder="お問い合わせの件名"
        error={!!errors.title}
        helperText={errors.title?.message}
                fullWidth
        margin="none"

                slotProps={{
    formHelperText: {sx: {fontSize: 14}}
  }}

                sx={{my: 2}}

        {...register('title')}
      />

      <TextField
      id="message"
        label="本文"
        autoComplete="off"
        placeholder="お問い合わせ内容をご記入ください"
        multiline
        rows={5}
        error={!!errors.message}
        helperText={errors.message?.message}
                fullWidth
        margin="none"

                slotProps={{
    formHelperText: {sx: {fontSize: 14}}
  }}

                sx={{my: 2}}

        {...register('message')}

      />

<Controller
  name="agreement"
  control={control}//左記のcontrolはuseForm()から取得したcontrolでフォーム全体の状態管理・制御オブジェクトであり司令塔、Controllerに渡すことでそのフォーム要素をRHFの管理下に置く、
  //Controller自体はMUIコンポーネントと司令塔を繋ぐ役割、register()を使用しないので自分でこのフィールドはcontrolに紐付けてねと渡す必要がある、
  //送信後にdefaultValuesに戻るように設定しているがプライバシーポリシーのチェックボックスが連動しないためControllerにて実装するもの
  defaultValue={false}
  render={({field}) => (//ControllerはFormControlLabelとCheckboxに対してRHFが管理する入力操作や値(value, onChange, onBlurなど)をfieldとして渡す、
  //このfieldを適切に渡すことでRHFとMUIコンポーネントが正しく連携する
    <FormControlLabel
      control={//左記のcontrolは上記のcontrolとは全く別物でMUIが用意しているpropsの名前、どのUI部品をラベルと組み合わせるかを指定するためのもの
        <Checkbox
        {...field}
        id="agreement"
          checked={!!field.value}
          onChange={e => field.onChange(e.target.checked)}
          sx={{py: 0}}
        />
      }
      label="プライバシーポリシーに同意する"
      sx={{ display: 'block', mt: 2, mb: errors.agreement ? 0 : 2 }}
    />
  )}
/>
      {errors.agreement && (
        <Box sx={{color: 'error.main', fontSize: 14, ml: 2, mb: 2}}>{errors.agreement.message}</Box>
      )}

      <Button type="submit" variant="contained" sx={{my: 2}} disabled={isSubmitting}>{/* disabled={isSubmitting}によりisSubmittingがtrueのときはボタンが無効化、
      送信中(onSubmit内のPromiseが解決するまで)はtrueになり、送信中に連打されないようにするための防止策 */}
        {isSubmitting ? '送信中…' : '送信'}
      </Button>
    </Container>
  );
}
